layout.css:
body {
    margin: 0;
    font-family: Arial, sans-serif;
    background: #0f172a;
    color: #f1f5f9;
}
.container {
    max-width: 800px;
    margin: auto;
    padding: 20px;
}
h2 {
    margin-top: 0;
    color: #38bdf8;
}
.listBtn, .backBtn {
    display: block;
    width: 100%;
    text-align: left;
    padding: 12px;
    margin: 6px 0;
    background: #1e293b;
    border: 1px solid #334155;
    color: #f1f5f9;
    cursor: pointer;
    border-radius: 6px;
    font-size: 15px;
}
.listBtn:hover,
.backBtn:hover {
    background: #334155;
}
.highlight {
    border-left: 4px solid #38bdf8;
}
.step {
    padding: 10px 12px;
    background: #1e293b;
    border-radius: 6px;
    margin: 8px 0;
    border: 1px solid #334155;
}
.stepRow {
    display: flex;
    align-items: center;
    gap: 10px;
}
#searchInput {
    width: 100%;
    padding: 12px;
    border-radius: 6px;
    border: none;
    margin-bottom: 10px;
    font-size: 15px;
}
#searchResults {
    background: #1e293b;
    border-radius: 6px;
    border: 1px solid #334155;
    display: none;
    margin-bottom: 10px;
}
.searchResult {
    padding: 10px;
    cursor: pointer;
    border-bottom: 1px solid #334155;
}
.searchResult:hover {
    background: #334155;
}

